// 📖 Journal: a book of every fish and bird. Animals you haven't caught are only a "?";
// caught ones show their picture and name, and open a rundown on the facing page.
// All the book art (cover, paper, frames, tabs, ribbon…) is pixel art generated by
// art/journal/journal_gen.py, served from /journal/*.png.

import { BIOMES, type BiomeId, BIRDS, FISH, type AlbumEntry } from '@hearthwood/shared';
import { state } from '../../../state.ts';
import { h } from '../../dom.ts';
import { BIOME_ICON } from '../../map.ts';
import { itemIcon, SEASON_ICON } from '../common.ts';
import { RUNDOWN } from '../journalText.ts';
import type { Hud } from '../../hud.ts';

const PER_PAGE = 16;
const ART = '/journal/';

interface Entry {
  id: string;
  name: string;
  sell: number;
  rarity: number;
  hours?: [number, number];
  seasons?: string[];
  /** Where it lives: biome ids. */
  biomes: string[];
  /** Extra where-to-look line (water type, beaches). */
  place: string;
  caught: AlbumEntry | undefined;
}

function fishEntries(): Entry[] {
  const a = state.album.fish;
  return FISH.map((f) => {
    const biomes = (Object.keys(BIOMES) as BiomeId[]).filter((b) => BIOMES[b].seaFish.includes(f.id) || BIOMES[b].freshFish.includes(f.id) || f.biomes?.includes(b));
    const place = f.water === 'sea' ? '🌊 In the sea' : f.water === 'river' ? '🏞️ In rivers' : '🪷 In ponds';
    return { id: f.id, name: f.name, sell: f.sell, rarity: f.rarity, hours: f.hours, seasons: f.seasons, biomes, place, caught: a[f.id] };
  });
}

function birdEntries(): Entry[] {
  const a = state.album.birds;
  return BIRDS.map((b) => ({
    id: b.id, name: b.name, sell: b.sell, rarity: b.rarity, hours: b.hours, seasons: b.seasons, biomes: b.biomes,
    place: b.perch === 'shore' ? '🏖️ On beaches' : '🌿 On grass and in trees', caught: a[b.id],
  }));
}

const hours = (hr?: [number, number]) => (hr ? `${String(hr[0]).padStart(2, '0')}:00 – ${String(hr[1]).padStart(2, '0')}:00` : 'All day');
const seasons = (s?: string[]) => (s ? s.map((x) => `${SEASON_ICON[x] ?? ''} ${x[0].toUpperCase()}${x.slice(1)}`).join(', ') : 'All year');
const rarity = (r: number) => (r >= 8 ? 'Common' : r >= 4 ? 'Uncommon' : r >= 2 ? 'Rare' : 'Very rare');
const biomeName = (b: string) => `${BIOME_ICON[b as BiomeId] ?? ''} ${BIOMES[b as BiomeId]?.name ?? b}`;

const img = (name: string, cls = '', alt = '') => h('img', { src: `${ART}${name}.png`, class: `pix ${cls}`, alt, draggable: 'false' });

/** The whole book. Re-rendered on every state change (hud.live). */
export function albumPanel(hud: Hud, root: HTMLElement) {
  const fish = hud.albumTab === 'fish';
  const entries = fish ? fishEntries() : birdEntries();
  const caught = entries.filter((e) => e.caught).length;
  const pages = Math.max(1, Math.ceil(entries.length / PER_PAGE));
  hud.albumPage = Math.min(hud.albumPage, pages - 1);
  const sel = entries.find((e) => e.id === hud.albumSel) ?? null;
  const go = (f: () => void) => () => { f(); hud.panelRefresh?.(); };

  // ── Left page: the list ──
  const grid = h('div', { class: 'jr-grid' });
  for (const e of entries.slice(hud.albumPage * PER_PAGE, (hud.albumPage + 1) * PER_PAGE)) {
    const n = entries.indexOf(e) + 1;
    grid.append(h('button', {
      class: `jr-slot${e.caught ? ' got' : ''}${sel?.id === e.id ? ' sel' : ''}`,
      title: e.caught ? e.name : `No. ${n} – not caught yet`,
      onclick: go(() => (hud.albumSel = sel?.id === e.id ? null : e.id)),
    },
    e.caught ? itemIcon(e.id, 'jr-ico') : img('question', 'jr-q', '?'),
    h('span', { class: 'jr-name' }, e.caught ? e.name : '?'),
    h('span', { class: 'jr-no' }, String(n).padStart(2, '0'))));
  }
  const left = h('section', { class: 'jr-page left' },
    img('flourish', 'jr-corner tl'), img('flourish', 'jr-corner bl'),
    h('h2', { class: 'jr-title' }, fish ? 'Fish' : 'Birds'),
    h('div', { class: 'jr-count' }, `${caught} / ${entries.length} caught`),
    img('divider', 'jr-divider'),
    grid,
    h('div', { class: 'jr-foot' },
      h('button', { class: 'jr-arrow', title: 'Previous page', disabled: hud.albumPage === 0, onclick: go(() => hud.albumPage--) }, img('arrow_left', '', '◀')),
      h('span', { class: 'jr-pageno' }, `${hud.albumPage + 1} / ${pages}`),
      h('button', { class: 'jr-arrow', title: 'Next page', disabled: hud.albumPage >= pages - 1, onclick: go(() => hud.albumPage++) }, img('arrow_right', '', '▶'))));

  // ── Right page: the rundown, or the cover page of this section ──
  const right = h('section', { class: 'jr-page right' }, img('flourish', 'jr-corner tr'), img('flourish', 'jr-corner br'), img('ribbon', 'jr-ribbon'));
  if (sel?.caught) right.append(...rundown(sel, entries.indexOf(sel) + 1, go(() => (hud.albumSel = null))));
  else if (sel)
    right.append(h('h2', { class: 'jr-title' }, `No. ${String(entries.indexOf(sel) + 1).padStart(2, '0')}`), img('divider', 'jr-divider'),
      h('div', { class: 'jr-big' }, img('question', 'jr-bigq', '?')),
      h('p', { class: 'jr-text center' }, 'Not caught yet.'),
      h('button', { class: 'jr-back', onclick: go(() => (hud.albumSel = null)) }, '← Back'));
  else {
    const all = fishEntries().filter((e) => e.caught).length + birdEntries().filter((e) => e.caught).length;
    right.append(
      h('h2', { class: 'jr-title' }, fish ? 'Fish of Hearthwood' : 'Birds of Hearthwood'), img('divider', 'jr-divider'),
      h('p', { class: 'jr-progress' }, h('b', {}, String(caught)), ` of ${entries.length} caught`),
      h('div', { class: 'jr-bar' }, h('div', { style: `width:${(100 * caught) / entries.length}%` })),
      h('p', { class: 'jr-text center' }, caught === 0
        ? (fish ? 'Cast your rod in the sea, rivers and ponds – every new catch gets its own page here.' : 'Catch birds with a net when they land – every new one gets its own page here.')
        : `Tap a ${fish ? 'fish' : 'bird'} to read about it.`),
    );
    if (all === FISH.length + BIRDS.length) right.append(h('p', { class: 'jr-text center' }, '🏆 Journal complete – amazing!'));
  }

  // ── The book: tabs, cover, the spread ──
  const tab = (id: 'fish' | 'birds', label: string) =>
    h('button', { class: `jr-tab ${id}${hud.albumTab === id ? ' on' : ''}`, title: label, onclick: go(() => { hud.albumTab = id; hud.albumPage = 0; hud.albumSel = null; }) },
      img(`tab_${id}`, '', label), h('span', {}, label));
  root.append(h('div', { class: `jr-book${sel ? ' has-sel' : ''}` },
    h('div', { class: 'jr-tabs' }, tab('fish', 'Fish'), tab('birds', 'Birds')),
    h('button', { class: 'jr-close', title: 'Close (K)', onclick: () => hud.close() }, '✕'),
    h('div', { class: 'jr-spread' }, left, h('div', { class: 'jr-gutter' }), right)));
}

function rundown(e: Entry, n: number, back: () => void): HTMLElement[] {
  const info = RUNDOWN[e.id];
  const c = e.caught!;
  const fact = (label: string, value: string) => h('div', { class: 'jr-fact' }, h('dt', {}, label), h('dd', {}, value));
  return [
    h('h2', { class: 'jr-title' }, e.name),
    img('divider', 'jr-divider'),
    h('div', { class: 'jr-head' },
      h('div', { class: 'jr-portrait' }, itemIcon(e.id, 'jr-bigico')),
      h('div', { class: 'jr-stamp' }, h('b', {}, `×${c.n}`), h('span', {}, 'caught'), h('small', {}, `No. ${String(n).padStart(2, '0')}`))),
    info ? h('p', { class: 'jr-text' }, info.text) : null,
    h('dl', { class: 'jr-facts' },
      info ? fact('Size', info.size) : null,
      fact('Where', `${e.place} · ${e.biomes.map(biomeName).join(', ') || 'Anywhere'}`),
      fact('When', hours(e.hours)),
      fact('Season', seasons(e.seasons)),
      fact('Rarity', rarity(e.rarity)),
      fact('Sells for', `🪙 ${e.sell}`),
      fact('First caught', `${new Date(c.first).toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' })} · ${biomeName(c.biome)}`)),
    h('button', { class: 'jr-back', onclick: back }, '← Back'),
  ].filter(Boolean) as HTMLElement[];
}
